en return ui.notif("your exec doesnt have setclipboard")end;setclipboard(tostring(rget(char.hrp,"CFrame").Position))end)cmds.add("copyjobid",false,function()if not setclipboard then return ui.notif("your exec doesnt have setclipboard")end;setclipboard(tostring(rget(game,"JobId")))end)cmds.add("copyplaceid",false,function()if not setclipboard then return ui.notif("your exec doesnt have setclipboard")end;setclipboard(tostring(rget(game,"PlaceId")))end)cmds.add("copyuserid",true,function(args)if not setclipboard then return ui.notif("your exec doesnt have setclipboard")end;local plr=funcs.qGetPlayer(args[1])or internal.plr;if plr then setclipboard(tostring(plr,"UserId"))end end)cmds.add("tptool",false,function()local tool=funcs.cinst("Tool",{Name="tptool",CanBeDropped=false,RequiresHandle=false,Parent=internal.plr:WaitForChild("Backpack")})rget(tool,"Activated"):Connect(function()if rget(internal.mouse,"Target")~=nil then rset(char.hrp,"CFrame",CFrame.new(rget(internal.mouse,"Hit").Position))end end)end)do local hasHumanoid={}cmds.add("triggerbot",false,function()signals.triggerbot=rget(serv.RunService,"RenderStepped"):Connect(function()local target=rget(internal.mouse,"Target")if target~=nil and(table.find(hasHumanoid,rget(target.Parent))or rget(target,"Parent"):FindFirstChildOfClass("Humanoid"))then if not table.find(hasHumanoid,rget(target.Parent))then table.insert(hasHumanoid,rget(target.Parent))end;pcall(mouse1press)end end)for i,v in next,hasHumanoid do if not v:IsDescendantOf(workspace)then table.remove(hasHumanoid,i)end end end)cmds.add("untriggerbot",false,function()if signals.triggerbot then signals.triggerbot:Disconnect()table.clear(hasHumanoid)end end)end;cmds.add("instantdodge",false,function()local lastHealth=rget(char.hum,"Health")signals.instantdodge=rget(char.hum,"HealthChanged"):Connect(function(health)if health>lastHealth then return else lastHealth=health end;if health>1 then local nearest,closestdist=nil,1/0;for i,v in next,workspace:QueryDescendants("Model:has(Humanoid)")do if v~=char and rget(rget(v,"Humanoid"),"Health")>0 then local dist=(v:GetPivot().Position-char:GetPivot().Position).Magnitude;if dist<closestdist then nearest=v;closestdist=dist end end end;if nearest then rset(char.hrp,"CFrame",nearest:GetPivot()*CFrame.new(.5,0,-3))end end end)end)cmds.add("uninstantdodge",false,function()if signals.instantdodge then signals.instantdodge:Disconnect()end end)do local velocity=funcs.cinst("LinearVelocity",{MaxForce=1/0,RelativeTo=Enum.ActuatorRelativeTo.Attachment0,Parent=workspace})local function disconnect()if signals.vfly then signals.vfly:Disconnect()end;rset(char.hum,"PlatformStand",false)rset(velocity,"Enabled",false)signals.humdied_vfly:Disconnect()end;cmds.add("vfly",false,function(args)local speed=tonumber(args[1])or 100;signals.vfly=rget(serv.RunService,"Heartbeat"):Connect(function(dt)rset(velocity,"Attachment0",rget(char.hrp,"RootAttachment"))rset(velocity,"Enabled",true)local move=funcs.getmovevector()*speed;rset(velocity,"VectorVelocity",move)rset(char.hrp,"CFrame",CFrame.new(rget(char.hrp,"CFrame").Position,rget(char.hrp,"CFrame").Position+rget(rget(workspace,"CurrentCamera"),"CFrame").LookVector))end)signals.humdied_vfly=rget(char.hum,"Died"):Connect(disconnect)end)cmds.add("unvfly",false,disconnect)end;do local function disconnect()if signals.god then signals.god:Disconnect()end;pcall(replicatesignal,internal.plr)end;cmds.add("god",false,function()local tools={}local touchinterests=0;if not firetouchinterest then return ui.notif("ur exec doesnt have firetouchinterest")end;if not replicatesignal then return ui.notif("ur exec doesnt have replicatesignal")end;char.hum:SetStateEnabled(Enum.HumanoidStateType.Dead,false)replicatesignal(rget(internal.plr,"Kill"))task.wait(math.min(internal.plr:GetNetworkPing()+.1,internal.plr:GetNetworkPing()*2))signals.god=rget(serv.RunService,"Heartbeat"):Connect(function(dt)touchinterests=0;for _,tool in next,workspace:QueryDescendants("Model:has(Humanoid) > 